const DETERMINERS = /^(a|an|the)\s+/i;
const TRAILING_PUNCTUATION = /[.,!?;:()"'[\]]+$/g;
const ENTITY_NAME_BAD_PATTERN = /^(~|[-→·•])|["'`[\]{}()]|→|=>|->|`|~[\d]/;
const ENTITY_NAME_ONLY_SYMBOLS = /^[^a-zA-Z0-9]+$/;
const ENTITY_NAME_HEADING = /^#/;
const ENTITY_NAME_ORDINAL_LIST = /^\d+[.)]\s/;

export function cleanText(raw: string): string {
	return raw.replace(TRAILING_PUNCTUATION, "").trim();
}

export function stripLeadingDeterminer(phrase: string): string {
	return phrase.replace(DETERMINERS, "").trim();
}

export function isExcludedNoun(candidate: string): boolean {
	const lower = candidate.toLowerCase();
	return lower.length < 2 || PRONOUNS.has(lower) || STOPWORDS.has(lower) || /^\d+$/.test(candidate);
}

/** Reject code fragments, punctuation-only text, and markdown structure. */
export function isValidEntityName(name: string): boolean {
	return (
		name.length >= 2 &&
		!ENTITY_NAME_ONLY_SYMBOLS.test(name) &&
		!ENTITY_NAME_BAD_PATTERN.test(name) &&
		!ENTITY_NAME_HEADING.test(name) &&
		!ENTITY_NAME_ORDINAL_LIST.test(name)
	);
}
